def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # The marked motif is a 2x2 pair of blocks on a diagonal.
    motif = ((0, 0), (0, 1), (1, 2), (1, 3))
    for r in range(h - 1):
        for c in range(w - 3):
            if all(grid[r + dr][c + dc] == 0 for dr, dc in motif):
                for dr, dc in motif:
                    out[r + dr][c + dc] = 6
    return out
